const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const known=x=>typeof x==='number'&&Number.isFinite(x);
export function treeMeaning(f){
 const missing=['moisture','surface','days','rain'].filter(k=>!known(f[k]));
 if(missing.length)return {title:'Primero necesitamos algunas pistas.',water:'Sin todas las lecturas, no sabemos cómo está el escenario.',heat:'Completa los controles o elige un ejemplo.',rain:'Un dato que falta no significa cero.',action:'Añade las lecturas que faltan antes de interpretar el árbol.',missing};
 const dry=f.moisture<18||f.days>12,hot=f.surface>=35;
 return {missing,dry,hot,title:dry&&hot?'Poca agua y mucho calor: presta atención.':dry?'El escenario muestra poca agua disponible.':hot?'El escenario muestra una superficie caliente.':'Las señales de agua y calor son más tranquilas.',water:dry?'Imagina una esponja que se está secando. El dato de la superficie sugiere revisar el agua del suelo.':'Imagina una esponja con agua. La superficie parece más húmeda; todavía hay que comprobar las raíces.',heat:hot?'Como un piso calentado por el sol: la superficie está caliente. Eso no nos dice la temperatura de las hojas.':'La superficie está menos caliente en este ejemplo. El árbol real puede sentir otras condiciones.',rain:f.rain>=35?'Ha llovido bastante en este escenario. Conviene mirar hojas y drenaje; la lluvia por sí sola no demuestra una enfermedad.':f.rain<10?'Ha llovido poco. No des por hecho que la lluvia alcanzó para el cultivo.':'Hay lluvia de apoyo. No sabemos cuánta agua llegó hasta las raíces.',action:dry?'Revisa la humedad bajo la superficie con un técnico antes de decidir el riego.':hot?'Observa las hojas y flores en campo y contrasta la temperatura con una medición.':'Observa tu parcela y registra cambios. Esta imagen no confirma que el árbol esté sano.'};
}
export function treePicture(f,growth=5){
 const state=treeMeaning(f),dry=!!state.dry,hot=!!state.hot,level=Math.max(0,Math.min(5,growth));
 const colors=dry?['#718445','#8e9b55','#a7ad69','#637b42']:['#285936','#39723d','#508b43','#6a9d4c'];
 let crown='';
 if(level>=3){const radius=level===3?42:level===4?72:112,cy=level===3?204:level===4?166:133;
 for(let i=0;i<48;i++){const angle=i*2.39996,rr=Math.sqrt((i+.5)/48)*radius,x=320+Math.cos(angle)*rr,y=cy+Math.sin(angle)*rr*.7,r=13+(i%5)*3;crown+=`<g class="tree-foliage" style="--sway:${i%4*-.8}s"><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r}" fill="${colors[i%4]}"/>${Array.from({length:7},(_,j)=>{const a=j*Math.PI*2/7;return `<ellipse cx="${(x+Math.cos(a)*r).toFixed(1)}" cy="${(y+Math.sin(a)*r).toFixed(1)}" rx="7" ry="4" transform="rotate(${j*51} ${x} ${y})" fill="${colors[i%4]}"/>`;}).join('')}</g>`;}}
 const sprout=level>0&&level<3?`<path d="M320 291Q306 243 320 ${level===1?241:192}" fill="none" stroke="#467342" stroke-width="4"/><path d="M315 260Q277 250 287 231Q312 229 315 260M316 245Q341 218 352 236Q342 254 316 245${level===2?'M317 217Q291 205 298 188Q321 192 317 217M320 202Q338 177 345 188Q347 201 320 202':''}" fill="#66a554"/>`:'';
 return `<svg viewBox="0 0 640 390" role="img" aria-label="${['Semilla','Brote','Planta joven','Árbol pequeño','Árbol en desarrollo','Árbol adulto'][level]}. Representación educativa, no predicción de crecimiento."><rect width="640" height="390" rx="22" fill="${hot?'#fbf0d9':'#f2f6ec'}"/><circle cx="535" cy="68" r="40" fill="#f1c868" opacity=".2"/><circle cx="535" cy="68" r="23" fill="#efbd61"/><path d="M0 302Q160 282 300 300T640 300V390H0Z" fill="${dry?'#c4ad89':'#ac9c82'}"/><path d="M0 337Q180 315 340 337T640 334V390H0Z" fill="#89775f"/><ellipse cx="320" cy="298" rx="135" ry="14" fill="#715c4533"/>
 ${level>=3?`<g fill="none" stroke="#dac8a5" stroke-width="2"><path d="M320 299q-25 30-86 54m86-54q20 40 89 54m-89-54v66m-40-40-15 39m86-35 18 33"/></g><path d="M309 300Q321 230 313 ${level===3?205:150}L324 ${level===3?205:150}Q319 232 333 300Z" fill="#70533d"/><path d="M321 264L${level===3?294:271} ${level===3?222:183}M322 247L${level===3?346:370} ${level===3?213:170}M318 211L298 166" fill="none" stroke="#70533d" stroke-width="5"/>${crown}`:sprout}
 ${level===0?'<ellipse cx="319" cy="290" rx="13" ry="7" transform="rotate(-23 319 290)" fill="#916c43" stroke="#5a482f"/><path d="M313 292l10-8" stroke="#c7b18b"/>':''}
 ${!state.missing.length?Array.from({length:dry?3:10},(_,i)=>`<circle class="tree-water" cx="${214+i*24}" cy="${335+(i%3)*13}" r="4" fill="#a9d8d0"/>`).join(''):''}
 ${hot?'<g class="tree-heat" fill="none" stroke="#bf823d" stroke-width="2"><path d="M150 234q-9-13 0-26t0-26M480 234q9-13 0-26t0-26"/></g>':''}
 <text x="22" y="29" fill="#546b52" font-size="11">ILUSTRACIÓN DEL ESCENARIO</text><text x="22" y="372" fill="#fff3dd" font-size="11">Raíces ilustradas · no medidas por el satélite</text></svg>`;
}
export function mountTreeLab(container,farm,options={}){
 let state={...farm},growth=5,part='water';const labels=['Semilla','Brote','Planta joven','Árbol pequeño','En desarrollo','Árbol adulto'];
 const specs=[['moisture','Agua en la superficie','%',0,100,1],['surface','Calor de la superficie','°C',-50,80,.5],['days','Tiempo desde el riego','días',0,3650,1],['rain','Lluvia en una semana','mm',0,5000,1]];
 container.innerHTML=`<section class="tree-lab"><div class="tree-lab-head"><div><small>EXPLORA · TOCA · COMPRENDE</small><h2>Tu árbol te ayuda a entender.</h2><p>Cambia una condición y observa la diferencia. Es una simulación educativa de ${esc(farm.crop||'tu cultivo')}.</p></div><button type="button" data-reset>↺ Volver a mis datos</button></div><div class="tree-lab-layout"><div><div class="tree-picture"></div><div class="tree-growth" role="group" aria-label="Etapas ilustrativas de crecimiento">${labels.map((l,i)=>`<button type="button" data-growth="${i}" aria-pressed="${i===5}"><span>${i+1}</span>${l}</button>`).join('')}</div><p class="tree-caption">Explora cómo cambia la forma de un árbol al crecer. Las etapas no representan años, rendimiento ni crecimiento previsto.</p><div class="tree-parts" role="group" aria-label="Descubrir partes del árbol"><button type="button" data-part="water">≈ Raíces y agua</button><button type="button" data-part="heat">☀ Hojas y calor</button><button type="button" data-part="rain">☂ Lluvia y suelo</button></div><p class="tree-part-story" role="status"></p></div><div class="tree-controls"><div class="tree-presets"><button type="button" data-preset="water">💧 Más agua</button><button type="button" data-preset="dry">☀ Suelo seco</button><button type="button" data-preset="hot">♨ Más calor</button></div><p class="tree-caption">Son ejemplos para aprender, no instrucciones de riego.</p>${specs.map(([k,l,u,min,max,step])=>`<label class="tree-control">${l}<output data-value="${k}"></output><input type="range" data-input="${k}" min="${k==='days'?0:k==='rain'?0:min}" max="${k==='days'?Math.max(30,state[k]||0):k==='rain'?Math.max(100,state[k]||0):max}" step="${step}" value="${known(state[k])?state[k]:0}"><small data-explain="${k}"></small></label>`).join('')}<p class="tree-caption">Mover controles cambia un escenario hipotético. La humedad superficial no mide el agua junto a las raíces.</p></div></div><div class="tree-takeaway" aria-live="polite"><strong></strong><p></p></div></section>`;
 const $=s=>container.querySelector(s);
 function draw(emit=false){const m=treeMeaning(state);$('.tree-picture').innerHTML=treePicture(state,growth);$('.tree-part-story').textContent=m[part];$('.tree-takeaway strong').textContent=m.title;$('.tree-takeaway p').textContent='Qué revisar: '+m.action;
 const hints={moisture:known(state.moisture)?`${state.moisture}% es la lectura superficial; no es un porcentaje de salud del árbol.`:'Falta esta lectura.',surface:known(state.surface)?`${state.surface} °C describe la superficie. La predicción de la IA usa temperatura del aire, que es distinta.`:'Falta esta lectura.',days:known(state.days)?`Han pasado ${state.days} días desde el riego anotado.`:'Falta esta lectura.',rain:known(state.rain)?`${state.rain} mm equivale a ${state.rain} litros caídos sobre cada metro cuadrado en 7 días. No todo llega a las raíces.`:'Falta esta lectura.'};
 specs.forEach(([k,l,u])=>{$(`[data-value="${k}"]`).textContent=known(state[k])?`${state[k]} ${u}`:'Sin dato';$(`[data-explain="${k}"]`).textContent=hints[k];const el=$(`[data-input="${k}"]`);if(known(state[k]))el.value=state[k];});
 container.querySelectorAll('[data-growth]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.growth===growth)));container.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.part===part)));
 if(emit)options.onChange?.({...state});}
 container.querySelectorAll('[data-input]').forEach(el=>el.oninput=()=>{state[el.dataset.input]=Number(el.value);draw(true);});
 container.querySelectorAll('[data-growth]').forEach(b=>b.onclick=()=>{growth=+b.dataset.growth;draw();});
 container.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{part=b.dataset.part;draw();});
 container.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{if(b.dataset.preset==='water')state={...state,moisture:28,days:2};if(b.dataset.preset==='dry')state={...state,moisture:12,days:17};if(b.dataset.preset==='hot')state={...state,surface:39};draw(true);});
 $('[data-reset]').onclick=()=>{state={...farm};draw(true);};draw();
}

export function friendlyForecast(ml){
 if(!ml?.evaluation)return '<p>Primero carga el histórico y ejecuta el experimento para ver una explicación.</p>';
 const s=ml.scenario,e=ml.evaluation,fmt=n=>known(n)?n.toFixed(1):'Sin dato';
 const difference=s?s.rf-s.baseline:null;
 const trend=!s?'Faltan días consecutivos para calcular el siguiente día.':Math.abs(difference)<.4?'Se parece al último día del histórico.':difference>0?`El modelo calcula ${fmt(difference)} °C más que el último día del histórico.`:`El modelo calcula ${fmt(-difference)} °C menos que el último día del histórico.`;
 return `<div class="tree-forecast"><small>LA IA, EN PALABRAS SENCILLAS</small><h3>${esc(trend)}</h3>${s?`<div class="tree-forecast-numbers"><div>Último día del histórico<strong>${fmt(s.baseline)} °C</strong><small>${esc(s.origin)}</small></div><span aria-hidden="true">→</span><div>Estimación del día siguiente<strong>${fmt(s.rf)} °C</strong><small>${esc(s.date)}</small></div></div>`:''}<p>Esto estima la <strong>temperatura máxima del aire</strong>. Es un ejercicio con datos históricos de 2025, no el tiempo de mañana en tu finca.</p><h4>¿Cuánto se equivocó?</h4><p>En ${e.n} días de prueba, la distancia media entre lo calculado y lo observado fue de <strong>${fmt(e.rf.mae)} °C</strong>. Puede equivocarse más en un día concreto. Ese promedio no es un margen garantizado.</p><h4>¿Aprendió algo útil?</h4><p>${e.rf.mae<e.baseline.mae?'En estas pruebas, el modelo se equivocó menos que repetir la temperatura del día anterior.':'En estas pruebas, el modelo no mejoró la idea sencilla de repetir la temperatura del día anterior.'} Esa referencia sencilla se equivocó ${fmt(e.baseline.mae)} °C de media.</p><details><summary>¿Qué pistas utilizó?</summary><p>Combinó ${ml.model?.config?.trees??40} árboles de decisión: pequeñas reglas matemáticas, no árboles del campo. Miró temperaturas y lluvias de días anteriores.</p>${(ml.model?.importance||[]).map(x=>`<p>${esc(({'Tmax t':'Calor del último día','Tmax t−1':'Calor del día anterior','Media Tmax 7 días':'Calor medio de la semana','Lluvia t':'Lluvia del último día','Lluvia 7 días':'Lluvia de la semana'})[x.feature]||x.feature)}: ${Math.round(x.value*100)}% del peso del modelo. Es importancia al entrenar, no porcentaje de daño ni causa demostrada.</p>`).join('')}<p>MAE: error medio en grados. RMSE: otro resumen que da más peso a errores grandes (${fmt(e.rf.rmse)} °C). Ninguno es un porcentaje de acierto.</p></details></div>`;
}
